//! The generated module owns one checked content snapshot; runtime needs no parser/filesystem.
use tsrust_compiler::documentation::MODEL_SOURCE as MODEL;

pub(super) fn module(json:&str,examples:&[tsrust_compiler::documentation::Example])->Result<String,String>{
 let encoded=tsrust_compiler::json_string(json).replace('\u{2028}',"\\u2028").replace('\u{2029}',"\\u2029");
 let has_components=examples.iter().any(|example|example.kind==tsrust_compiler::documentation::ExampleKind::Component);
 let result=if has_components{"Node|null"}else{"null"};
 let mut imports=if has_components{String::from("import {Node} from 'std:ui';\n")}else{String::new()};let mut registry=String::new();
 for (index,example) in examples.iter().enumerate(){if example.kind==tsrust_compiler::documentation::ExampleKind::Component{
  imports.push_str(&format!("import {{{} as DocsExample{index}}} from {};\n",example.export,tsrust_compiler::json_string(&format!("../../{}",example.source))));
  registry.push_str(&format!("if(id=={}){{return DocsExample{index}();}}\n",tsrust_compiler::json_string(&example.id)));
 }}
 for example in examples.iter().filter(|example|example.kind==tsrust_compiler::documentation::ExampleKind::Code){registry.push_str(&format!("if(id=={}){{return null;}}\n",tsrust_compiler::json_string(&example.id)));}
 let source=format!("// Generated by tsrust docs content. Edit Markdown, examples and local components instead.\n{imports}\n{MODEL}\n/** Constructs an owned content snapshot with checked record/array/numeric conversion. */\nexport function loadCatalog():DocCatalog {{return JSON.parse<DocCatalog>({encoded});}}\n/** Runs only configured checked local component exports; code-only examples have no preview. */\nexport function renderExample(id:ReadOnly<string>):{result}{{{registry}throw 'Unknown documentation example';}}\n");
 tsrust_compiler::format(&source).map_err(|error|error.message)
}
